-- Mock orders for the seeded customers (see AuthDb.sql) and products (see CatalogDb.sql).
-- Item names and prices are snapshots of the catalog rows. Payment rows for these orders are in PaymentDb.sql.
-- No Pending orders: nothing would ever answer their payment request. Safe to rerun: existing rows are left alone.
BEGIN;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- Self-check: every seeded order's total must equal the sum of its items
DO $$
DECLARE mismatches text;
BEGIN
    SELECT string_agg(o."Id"::text, ', ') INTO mismatches
    FROM "Orders" o
    JOIN (SELECT "OrderId", SUM("UnitPrice" * "Quantity") AS total FROM "OrderItems" GROUP BY "OrderId") i ON i."OrderId" = o."Id"
    WHERE o."Id"::text LIKE '0e000000-%' AND o."TotalAmount" <> i.total;

    IF mismatches IS NOT NULL THEN
        RAISE EXCEPTION 'Seeded order totals do not match their items: %', mismatches;
    END IF;
END $$;

COMMIT;
